<template>
  <div class="page-head"><div><h2>安全作业</h2><span class="muted">施工水害相关现场核查事项、人工记录与闭环归档</span></div><div class="actions"><n-button tag="a" :href="api.assistanceCsvUrl(currentProjectId||undefined)" download>导出事项CSV</n-button><n-button tag="a" :href="api.assistanceVerificationCsvUrl(currentProjectId||undefined)" download>导出核查CSV</n-button><n-button type="primary" @click="manualOpen=true">人工新增事项</n-button></div></div>
  <div class="stat-grid compact"><metric-card label="待核查事项" :value="String(summary.pending_count)" tone="blue"/><metric-card label="优先核查事项" :value="String(summary.priority_count)" tone="red"/><metric-card label="已核验" :value="String(summary.verified_count)" tone="purple"/><metric-card label="已闭环" :value="String(summary.closed_count)" tone="green"/></div>
  <n-card class="filters"><div class="filter-grid"><n-select v-model:value="filters.status" clearable :options="statusOptions" placeholder="全部状态"/><n-select v-model:value="filters.priority_level" clearable :options="priorityOptions" placeholder="全部优先级"/><n-button :loading="loading" @click="load">查询</n-button></div></n-card>
  <n-card><n-data-table v-if="loading||rows.length" :loading="loading" :columns="columns" :data="rows" :pagination="{pageSize:12}"/><div v-else class="empty-table-panel"><div class="onboarding-mark"><img src="/icons/shield-check.svg" alt=""></div><h4>当前没有待处理的作业辅助事项</h4><p>可从风险研判成果生成事项，也可按现场情况人工建立核查任务。</p><n-button type="primary" @click="manualOpen=true">人工新增事项</n-button></div></n-card>

  <n-drawer v-model:show="detailOpen" width="min(860px,94vw)"><n-drawer-content title="作业辅助事项详情" closable><template v-if="detail">
    <n-descriptions bordered :column="2"><n-descriptions-item label="事项名称">{{detail.title}}</n-descriptions-item><n-descriptions-item label="当前状态"><n-tag :type="statusType(detail.status)">{{detail.status_label}}</n-tag></n-descriptions-item><n-descriptions-item label="项目">{{detail.project_name||'未关联项目'}}</n-descriptions-item><n-descriptions-item label="关注对象">{{[detail.work_area_name,detail.equipment_name].filter(Boolean).join(' / ')||'项目整体'}}</n-descriptions-item><n-descriptions-item label="事项类型">{{detail.assistance_type_label}}</n-descriptions-item><n-descriptions-item label="优先级">{{detail.priority_label}}</n-descriptions-item><n-descriptions-item label="生成来源">{{detail.source_label}}</n-descriptions-item><n-descriptions-item label="规则版本">{{detail.rule_version}}</n-descriptions-item></n-descriptions>
    <h4>为什么生成这条事项</h4><p>{{detail.source_summary||'人工创建事项，未填写生成依据。'}}</p>
    <h4>成果追溯链</h4><div v-if="trace" class="trace-chain"><span>原始数据 <b>{{trace.dataset_ids.length}}</b></span><i>→</i><span>识别成果 <b>{{trace.inference_result_ids.length}}</b></span><i>→</i><span>变化分析 <b>{{trace.change_analysis_id?'1':'0'}}</b></span><i>→</i><span>风险研判 <b>{{trace.risk_assessment_id?'1':'0'}}</b></span><i>→</i><span>作业辅助 <b>1</b></span></div><n-empty v-else description="人工事项暂无自动成果追溯链"/>
    <h4>多源证据</h4><div v-if="Object.keys(detail.evidence||{}).length" class="evidence"><n-collapse><n-collapse-item v-for="(value,key) in detail.evidence" :key="key" :title="evidenceLabel(String(key))"><pre>{{JSON.stringify(value,null,2)}}</pre></n-collapse-item></n-collapse></div><n-empty v-else description="暂无相关数据"/>
    <h4>系统辅助建议</h4><p>{{detail.recommendation_text||'未填写'}}</p>
    <h4>现场核查清单</h4><n-checkbox v-for="item in detail.inspection_checklist" :key="item" disabled>{{item}}</n-checkbox><p class="muted">清单由现场人员核查，系统不自动填写是或否。</p>
    <h4>人工核查结果</h4><n-data-table v-if="detail.verifications?.length" :columns="verificationColumns" :data="detail.verifications" :pagination="false"/><n-empty v-else description="暂无人工核查记录"/>
    <div class="detail-actions"><n-button v-if="detail.status==='PENDING'" @click="setStatus('IN_PROGRESS')">开始核查</n-button><n-button v-if="!['CLOSED','CANCELLED'].includes(detail.status)" type="primary" @click="verifyOpen=true">记录人工核查</n-button><n-button v-if="detail.status==='VERIFIED'" type="success" @click="closeOpen=true">完成该事项</n-button><n-button tag="a" target="_blank" :href="api.assistanceHtmlUrl(detail.id)">HTML报告</n-button><n-button tag="a" :href="api.assistancePdfUrl(detail.id)" download>PDF报告</n-button></div>
    <p class="boundary">已核验只表示人工核验已经完成，不等于区域安全。本系统不提供安全通行许可或停复工审批。</p>
  </template></n-drawer-content></n-drawer>

  <n-modal v-model:show="manualOpen" preset="card" title="人工新增作业辅助事项" class="dialog"><div class="form-grid"><n-select v-model:value="manual.project_id" clearable :options="projectOptions" placeholder="项目（可选）"/><n-select v-model:value="manual.assistance_type" :options="typeOptions"/><n-input v-model:value="manual.title" placeholder="事项名称"/><n-select v-model:value="manual.priority_level" :options="priorityOptions"/><n-input v-model:value="manual.source_summary" type="textarea" placeholder="人工创建依据"/><n-input v-model:value="manual.recommendation_text" type="textarea" placeholder="辅助建议"/></div><template #footer><n-button @click="manualOpen=false">取消</n-button><n-button type="primary" @click="createManual">保存</n-button></template></n-modal>
  <n-modal v-model:show="verifyOpen" preset="card" title="记录现场人工核查" class="dialog"><div class="form-grid"><n-select v-model:value="verification.verification_result" :options="resultOptions"/><n-input v-model:value="verification.finding_text" type="textarea" placeholder="现场发现"/><n-input v-model:value="verification.action_note" type="textarea" placeholder="后续动作记录"/><n-input v-model:value="verification.attachment_note" placeholder="附件说明（可选，不上传文件）"/></div><template #footer><n-button @click="verifyOpen=false">取消</n-button><n-button type="primary" @click="saveVerification">保存核查结果</n-button></template></n-modal>
  <n-modal v-model:show="closeOpen" preset="dialog" title="确认完成该事项" positive-text="确认闭环" negative-text="取消" @positive-click="closeItem"><n-input v-model:value="closeNote" type="textarea" placeholder="填写闭环说明（必填）"/><p class="muted">事项闭环由用户主动确认；历史事项和核查记录将继续保留。</p></n-modal>
</template>

<script setup lang="ts">
import{computed,h,onMounted,ref,watch}from'vue'
import{NButton,NTag,useMessage}from'naive-ui'
import MetricCard from'../components/MetricCard.vue'
import{api}from'../api'
import{currentProjectId}from'../composables/projectContext'
import type{AssistanceSummary,AssistanceVerification,ConstructionProject,OperationAssistance}from'../types'
import{formatDateTime}from'../utils/format'
const msg=useMessage(),rows=ref<OperationAssistance[]>([]),detail=ref<OperationAssistance|null>(null),trace=ref<any>(null),projects=ref<ConstructionProject[]>([]),loading=ref(false),detailOpen=ref(false),manualOpen=ref(false),verifyOpen=ref(false),closeOpen=ref(false),closeNote=ref('')
const summary=ref<AssistanceSummary>({pending_count:0,priority_count:0,verified_count:0,closed_count:0,status_counts:{}}),filters=ref({status:null as string|null,priority_level:null as string|null})
const statusOptions=[{label:'待核查',value:'PENDING'},{label:'核查中',value:'IN_PROGRESS'},{label:'已核验',value:'VERIFIED'},{label:'已闭环',value:'CLOSED'},{label:'已取消',value:'CANCELLED'}],priorityOptions=[{label:'一般',value:'NORMAL'},{label:'重点',value:'IMPORTANT'},{label:'优先',value:'URGENT'}]
const typeOptions=[{label:'区域巡检',value:'AREA_INSPECTION'},{label:'设备周边环境核查',value:'EQUIPMENT_ENV_CHECK'},{label:'通行条件核验',value:'PASSAGE_CONDITION_CHECK'},{label:'复工作业核验',value:'RESUME_WORK_CHECK'},{label:'应急协同',value:'EMERGENCY_COORDINATION'},{label:'其他',value:'OTHER'}]
const resultOptions=[{label:'问题已确认',value:'ISSUE_CONFIRMED'},{label:'未发现明显异常',value:'NO_OBVIOUS_ISSUE'},{label:'需要进一步核查',value:'NEEDS_FURTHER_CHECK'},{label:'现场条件已有改善',value:'CONDITION_IMPROVED'},{label:'暂无法核验',value:'UNABLE_TO_VERIFY'}]
const manual=ref({project_id:null as string|null,assistance_type:'AREA_INSPECTION',title:'',priority_level:'NORMAL',source_summary:'',recommendation_text:''}),verification=ref({verification_result:'NEEDS_FURTHER_CHECK',finding_text:'',action_note:'',attachment_note:'',checklist:[] as Record<string,unknown>[]})
const projectOptions=computed(()=>projects.value.map(x=>({label:x.project_name,value:x.id}))),statusType=(s:string)=>s==='CLOSED'?'success':s==='CANCELLED'?'default':s==='VERIFIED'?'info':s==='IN_PROGRESS'?'warning':'error'
const evidenceLabel=(key:string)=>({risk_assessment:'水害研判',change_analysis:'时空变化',work_area_impact:'施工区域影响',equipment_risk_link:'设备关联',terrain:'DEM地形',rainfall:'降雨背景',uav:'无人机复核'} as Record<string,string>)[key]||key
async function load(){loading.value=true;try{const q=new URLSearchParams();if(currentProjectId.value)q.set('project_id',currentProjectId.value);if(filters.value.status)q.set('status',filters.value.status);if(filters.value.priority_level)q.set('priority_level',filters.value.priority_level);[rows.value,summary.value]=await Promise.all([api.assistanceRecords(q.toString()),api.assistanceSummary(currentProjectId.value||undefined)])}catch(e:any){msg.error(e.message)}finally{loading.value=false}}
async function open(row:OperationAssistance){try{[detail.value,trace.value]=await Promise.all([api.assistanceRecord(row.id),api.assistanceTrace(row.id)]);detailOpen.value=true}catch(e:any){msg.error(e.message)}}
async function refreshDetail(){if(detail.value)detail.value=await api.assistanceRecord(detail.value.id);await load()}
async function setStatus(status:string){if(!detail.value)return;try{await api.updateAssistance(detail.value.id,{status});await refreshDetail();msg.success('事项状态已更新')}catch(e:any){msg.error(e.message)}}
async function createManual(){if(!manual.value.title.trim()){msg.warning('请填写事项名称');return}try{await api.createAssistance({...manual.value,project_id:manual.value.project_id||undefined});manualOpen.value=false;manual.value={project_id:currentProjectId.value,assistance_type:'AREA_INSPECTION',title:'',priority_level:'NORMAL',source_summary:'',recommendation_text:''};await load();msg.success('人工事项已创建')}catch(e:any){msg.error(e.message)}}
async function saveVerification(){if(!detail.value)return;try{await api.createAssistanceVerification(detail.value.id,verification.value);verifyOpen.value=false;verification.value={verification_result:'NEEDS_FURTHER_CHECK',finding_text:'',action_note:'',attachment_note:'',checklist:[]};await refreshDetail();msg.success('人工核查结果已记录')}catch(e:any){msg.error(e.message)}}
async function closeItem(){if(!detail.value||!closeNote.value.trim()){msg.warning('请填写闭环说明');return false}try{await api.closeAssistance(detail.value.id,closeNote.value.trim());closeNote.value='';await refreshDetail();msg.success('事项已闭环');return true}catch(e:any){msg.error(e.message);return false}}
const columns=[{title:'优先级',render:(r:OperationAssistance)=>h(NTag,{type:r.priority_level==='URGENT'?'error':r.priority_level==='IMPORTANT'?'warning':'default'},{default:()=>r.priority_label}),width:90},{title:'事项名称',key:'title',ellipsis:{tooltip:true},width:230},{title:'项目',render:(r:OperationAssistance)=>r.project_name||'未关联项目',width:160},{title:'施工区域',render:(r:OperationAssistance)=>r.work_area_name||'--',width:150},{title:'关联设备',render:(r:OperationAssistance)=>r.equipment_name||'--',width:140},{title:'事项类型',key:'assistance_type_label',width:150},{title:'状态',render:(r:OperationAssistance)=>h(NTag,{type:statusType(r.status)},{default:()=>r.status_label}),width:90},{title:'数据来源',key:'source_label',width:115},{title:'生成时间',render:(r:OperationAssistance)=>formatDateTime(r.created_at),width:160},{title:'操作',render:(r:OperationAssistance)=>h(NButton,{size:'small',onClick:()=>open(r)},{default:()=>'详情'}),width:80}]
const verificationColumns=[{title:'核查时间',render:(r:AssistanceVerification)=>formatDateTime(r.verified_at),width:170},{title:'核查结果',key:'verification_result_label',width:150},{title:'现场发现',render:(r:AssistanceVerification)=>r.finding_text||'未填写'},{title:'后续记录',render:(r:AssistanceVerification)=>r.action_note||'未填写'}]
watch(currentProjectId,()=>{manual.value.project_id=currentProjectId.value;void load()});onMounted(async()=>{try{projects.value=await api.projects();manual.value.project_id=currentProjectId.value;await load()}catch(e:any){msg.error(e.message)}})
</script>
<style scoped>.actions,.detail-actions{display:flex;gap:8px;flex-wrap:wrap}.compact{margin-bottom:14px}.filters{margin-bottom:14px}.filter-grid{display:grid;grid-template-columns:220px 220px max-content;gap:10px}.dialog{width:min(680px,92vw)}.form-grid{display:grid;gap:12px}.evidence pre{white-space:pre-wrap;font-size:12px}.trace-chain{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.trace-chain span{padding:10px 12px;border:1px solid var(--border);border-radius:6px;background:var(--surface-subtle)}.trace-chain i{color:#667085}.n-checkbox{display:block;margin:8px 0}.detail-actions{margin-top:18px}.boundary{margin-top:18px;padding:12px;border-left:3px solid #9a7b46;background:rgba(154,123,70,.08)}@media(max-width:700px){.filter-grid{grid-template-columns:1fr}.trace-chain i{display:none}}
</style>
